INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Definiert die Präfixlänge bei IPv6 den Netzwerkteil einer Adresse?', 2, '[{"text": "Ja", "correct": true, "because": "Die Präfixlänge gibt an, wie viele Bits das Netzwerk ausmachen"}, {"text": "Nein", "correct": false, "because": "Das ist die Hauptfunktion der Präfixlänge"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist /64 eine häufig verwendete Präfixlänge in IPv6-Netzwerken?', 2, '[{"text": "Ja", "correct": true, "because": "/64 ist Standard für SLAAC und viele Netze"}, {"text": "Nein", "correct": false, "because": "/64 ist weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Präfixlänge bei IPv6 größer als 128 Bits sein?', 2, '[{"text": "Nein", "correct": true, "because": "IPv6-Adressen haben maximal 128 Bits"}, {"text": "Ja", "correct": false, "because": "Über 128 Bits ist unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird die Präfixlänge bei IPv6 in der CIDR-Notation angegeben?', 2, '[{"text": "Ja", "correct": true, "because": "z. B. 2001:db8::/64 ist CIDR-Format"}, {"text": "Nein", "correct": false, "because": "CIDR ist Standard für IPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert SLAAC immer eine Präfixlänge von /64?', 2, '[{"text": "Ja", "correct": true, "because": "SLAAC benötigt /64 für die Interface-ID-Generierung"}, {"text": "Nein", "correct": false, "because": "/64 ist zwingend für SLAAC"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits bleiben für die Interface-ID bei einer Präfixlänge von /64?', 2, '[{"text": "64 Bits", "correct": true, "because": "128 - 64 = 64 Bits für die Interface-ID"}, {"text": "48 Bits", "correct": false, "because": "Das wäre bei /80"}, {"text": "32 Bits", "correct": false, "because": "Das wäre bei /96"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlänge wird typischerweise für ein lokales IPv6-Subnetz verwendet?', 3, '[{"text": "/64", "correct": true, "because": "Standard für Subnetze und SLAAC"}, {"text": "/48", "correct": false, "because": "Eher für Organisationen"}, {"text": "/128", "correct": false, "because": "Nur eine Adresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen, wenn ein /48-Netz in /56-Netze unterteilt wird?', 2, '[{"text": "256", "correct": true, "because": "2^(56-48) = 256 Subnetze"}, {"text": "128", "correct": false, "because": "Zu niedrig"}, {"text": "512", "correct": false, "because": "Zu hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlänge entspricht einer einzelnen IPv6-Adresse?', 2, '[{"text": "/128", "correct": true, "because": "Alle 128 Bits definieren eine Adresse"}, {"text": "/64", "correct": false, "because": "Das ist ein Subnetz"}, {"text": "/96", "correct": false, "because": "Noch ein Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bedeutet eine Präfixlänge von /48 für ein IPv6-Netzwerk?', 2, '[{"text": "65.536 Subnetze mit /64", "correct": true, "because": "2^(64-48) = 65.536"}, {"text": "256 Subnetze mit /64", "correct": false, "because": "Das wäre /56"}, {"text": "1 Subnetz mit 48 Hosts", "correct": false, "because": "Hosts werden nicht so gezählt"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlängen sind bei IPv6 üblich?', 4, '[{"text": "/48", "correct": true, "because": "Typisch für Organisationen"}, {"text": "/64", "correct": true, "because": "Standard für Subnetze"}, {"text": "/128", "correct": true, "because": "Für einzelne Adressen"}, {"text": "/24", "correct": false, "because": "Typisch für IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Was beschreibt die Präfixlänge /64 bei 2001:db8::/64?', 3, '[{"text": "64 Bits für das Netzwerk", "correct": true, "because": "Erste 64 Bits sind Netzwerkteil"}, {"text": "64 Bits für die Interface-ID", "correct": true, "because": "Rest der 128 Bits"}, {"text": "Nur 64 Adressen", "correct": false, "because": "Es sind 2^64 Adressen"}, {"text": "Standard für SLAAC", "correct": true, "because": "SLAAC nutzt /64"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hat eine Präfixlänge von /56 statt /48?', 4, '[{"text": "Weniger Subnetze", "correct": true, "because": "2^8 statt 2^16 Subnetze"}, {"text": "Größere Subnetze", "correct": false, "because": "Subnetzgröße bleibt bei /64 gleich"}, {"text": "256 Subnetze möglich", "correct": true, "because": "2^(56-48) = 256"}, {"text": "Geeignet für kleinere Netze", "correct": true, "because": "Weniger Subnetze als /48"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen auf eine Präfixlänge von /128 zu?', 3, '[{"text": "Definiert eine einzelne Adresse", "correct": true, "because": "Alle 128 Bits sind festgelegt"}, {"text": "Keine Subnetze möglich", "correct": true, "because": "Kein Platz für Unterteilung"}, {"text": "Geeignet für SLAAC", "correct": false, "because": "SLAAC braucht /64"}, {"text": "Typisch für Endgeräte", "correct": true, "because": "z. B. Loopback"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixlängen könnten für ein kleines Unternehmensnetz passen?', 3, '[{"text": "/56", "correct": true, "because": "256 Subnetze à /64"}, {"text": "/64", "correct": true, "because": "Ein Subnetz mit vielen Adressen"}, {"text": "/48", "correct": true, "because": "65.536 Subnetze, auch für kleinere Netze"}, {"text": "/32", "correct": false, "because": "Zu groß für kleines Netz"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Präfixlänge von /64 ist Standard für Subnetze. b) /128 erlaubt Subnetze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "/64 ist Standard, /128 ist eine Adresse"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /48 erlaubt 65.536 /64-Subnetze. b) /64 ist für einzelne Geräte gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(64-48) = 65.536, /64 ist für Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Präfixlänge definiert den Netzwerkteil. b) /56 bietet mehr Subnetze als /48.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Präfixlänge ja, /56 hat weniger Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) SLAAC benötigt /64. b) /48 ist typisch für Endgeräte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SLAAC ja, /48 für Organisationen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) /56 hat 256 /64-Subnetze. b) Eine Präfixlänge von /0 ist sinnvoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^(56-48) = 256, /0 ist unpraktisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

